package net.officefloor.hq.app.plan;

import net.officefloor.hq.app.sheet.Sheet;
import net.officefloor.plugin.variable.Val;
import net.officefloor.web.ObjectResponse;

public class RespondWithPausedPlan {
    public void respond(@Val PlanPaused done, @Val Sheet sheet, ObjectResponse<PlanResponse> response) {
        response.send(PlanResponse.from(done.plan(), sheet.today()));
    }
}
EOF
Y='src/main/resources/officefloor/rest/api/sheets/{sheetId}/plans/{planId}'
mkdir -p "$Y"
for a in pause resume; do C=$([ $a = pause ] && echo PausePlan || echo ResumePlan)
cat > "$Y/$a.POST.yml" <<EOF
# ${a^} a plan on the sheet's today. A plan date on or after the day it was paused and before the day
# it was resumed is skipped. Pausing a paused plan, or resuming a running one, is a 400 and writes nothing.
# A viewer may change nothing: refused before anything is read or written.
viewer:
  class: net.officefloor.hq.app.role.CheckCanChange
  next: loadSheet
loadSheet:
  class: net.officefloor.hq.app.sheet.LoadSheet
  govern: [ transaction ]
  next: loadPlan
loadPlan:
  class: net.officefloor.hq.app.plan.LoadPlan
  govern: [ transaction ]
  next: $a
$a:
  class: net.officefloor.hq.app.plan.$C
  govern: [ transaction ]
  next: respond
respond:
  class: net.officefloor.hq.app.plan.RespondWithPausedPlan
  govern: [ transaction ]
EOF
done

